#pragma once

#include <cstdint>
#include <span>
#include <string_view>

/**
 * What an icon is made of, as data: the bundled sets are tables of these (generated by tools/icons/generate.py),
 * and an application registers its own the same way (IconRegistry::add).
 */
namespace psychic_ui {

    /**
     * How an element of an icon is painted, in the icon's color
     */
    enum class IconPaint : std::uint8_t {
        Stroke,
        Fill
    };

    /**
     * One element of an icon: SVG path data on the icon's grid, stroked or filled
     */
    struct IconElement {
        IconPaint        paint{IconPaint::Stroke};
        std::string_view d{};
    };

    /**
     * An icon: its elements on a square grid of `grid` units (16 for Pivotal's set, 24 for Lucide's), the
     * whole grid filling the icon's box.
     *
     * `stroke` is the width the source set strokes it with, in grid units, for reference: every icon is drawn
     * with the same visual weight, the `iconStrokeWidth` style, so icons from both sets match side by side.
     * Strokes have round caps and joins, as in both sets.
     */
    struct IconDefinition {
        std::string_view               name{};
        float                          grid{16.0f};
        float                          stroke{1.3f};
        std::span<const IconElement>   elements{};
    };

    namespace icons {
        /**
         * Pivotal's set (PivotalIcons.cpp), registered first
         */
        extern const std::span<const IconDefinition> pivotalIcons;
    }
}
